'use client';
import { useState, type ReactNode } from 'react';
import { ConvexReactClient, ConvexProvider } from 'convex/react';
import { Text, View } from 'react-native';


export function Providers({ children }: { children: ReactNode }) {
  const url = process.env.EXPO_PUBLIC_CONVEX_URL;

  if (!url) return <Text>Set EXPO_PUBLIC_CONVEX_URL in this app's .env.local.</Text>;

  return <Connection url={url}>{children}</Connection>;
}
function Connection({ url, children }: { url: string; children: ReactNode }) {
  const [client] = useState(() => new ConvexReactClient(url, { unsavedChangesWarning: false }));
  return <ConvexProvider client={client}><View style={{ flex: 1, padding: 24, paddingTop: 64 }}>{children}</View></ConvexProvider>;
}

